const defaultEvents=plans.flatMap((items,day)=>items.map((x,i)=>({id:`d${day}e${i}`,day,time:x[0],title:x[1],place:x[2],type:x[3],note:x[4],date:dayList[day].date,status:x[5]||'planned',verify:Boolean(x[6]),bookingStatus:x[7]||null,documents:[]})));
