const itineraryStorageKey='travel-tefuda.itinerary.v2';
const cloneEvents=list=>list.map(x=>({...x,documents:[...(x.documents||[])]}));
function validStoredEvent(x){return x&&Number.isInteger(x.day)&&x.day>=0&&x.day<dayList.length&&['time','title','place','type','note','date','status'].every(key=>typeof x[key]==='string')&&Array.isArray(x.documents);}
function loadEvents(){try{const value=JSON.parse(localStorage.getItem(itineraryStorageKey));return Array.isArray(value)&&value.every(validStoredEvent)?cloneEvents(value):cloneEvents(defaultEvents);}catch{return cloneEvents(defaultEvents);}}
function persistEvents(){try{localStorage.setItem(itineraryStorageKey,JSON.stringify(events));return true;}catch{return false;}}
