const state={page:'now',day:0,carry:'documents',docFilter:'全部',packMode:'daily',albumGroup:null,expenseTab:'summary',currency:'EUR',expenseCategory:'全部',concertTime:'19:00',timezone:'local',modal:null,modalHistory:[],attachEvent:null,importPhotosGroup:null,trigger:null};
const modal=$('#dialog');
const uid=()=>globalThis.crypto?.randomUUID?.() || 'id'+Date.now()+Math.random().toString(16).slice(2);
function notify(text){const node=$('#toast');node.textContent=text;node.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>node.classList.remove('visible'),2400);}
function parseHash(){const hash=location.hash.slice(1).split('/');state.page=['now','plan','carry','money'].includes(hash[0])?hash[0]:'now';if(state.page==='now')state.day=0;if(state.page==='carry'&&['documents','packing','album'].includes(hash[1]))state.carry=hash[1];}
function navigate(page,sub){state.page=page;if(sub)state.carry=sub;const target=page==='carry'?`carry/${state.carry}`:page;if(location.hash!==`#${target}`)location.hash=target;else render();window.scrollTo(0,0);}
function buttonsTabs(options,selected,action){return `<div class="segmented">${options.map(([id,label])=>`<button data-action="${action}" data-value="${id}" class="${id===selected?'active':''}" aria-pressed="${id===selected}">${label}</button>`).join('')}</div>`;}
function heading(title,sub,action){return `<div class="page-heading between"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action||''}</div>`;}
function section(title,action=''){return `<div class="section-title"><h2>${title}</h2>${action}</div>`;}
function linkButton(label,action,value=''){return `<button class="text-link" data-action="${action}" data-value="${e(value)}">${label}${icon('chevron')}</button>`;}
const weatherPlaces=[
 ['布达佩斯',47.4979,19.0402,'Europe/Budapest'],['维也纳',48.2082,16.3738,'Europe/Vienna'],
 ['Gosau',47.584,13.535,'Europe/Vienna'],['Gosausee',47.533,13.496,'Europe/Vienna'],
 ['St. Wolfgang',47.739,13.447,'Europe/Vienna'],['布拉格',50.0755,14.4378,'Europe/Prague'],
 ['布拉格',50.0755,14.4378,'Europe/Prague'],['布拉格',50.0755,14.4378,'Europe/Prague']
];
const weatherCache=new Map();
function weatherDay(){return state.page==='plan'?state.day:0;}
function weatherEntry(day=weatherDay()){return weatherCache.get(weatherPlaces[day][0]);}
function weatherWords(code){if(code===0)return '晴';if(code<=2)return '晴间多云';if(code===3)return '阴';if([45,48].includes(code))return '雾';if(code>=95)return '雷雨';if([71,73,75,77,85,86].includes(code))return '降雪';if(code>=51&&code<=82)return '降雨';return '天气状况待更新';}
function weatherStamp(value,day=weatherDay()){return new Intl.DateTimeFormat('zh-CN',{timeZone:weatherPlaces[day][3],month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value*1000));}
function weatherMiniContent(day=weatherDay()){const w=weatherEntry(day),city=weatherPlaces[day][0];return `${icon(w?.data?.weather_code===0?'sun':'cloud')}<span><b>${w?.status==='ready'?Math.round(w.data.temperature_2m)+'°':w?.status==='error'?'暂不可用':'获取中'}</b><br>${e(city)} · 当前${w?.status==='ready'?`<br>${weatherStamp(w.data.time,day)} 当地`:''}</span>`;}
function weatherMini(){const day=weatherDay(),loading=weatherEntry(day)?.status==='loading';queueMicrotask(()=>refreshWeather(false,day));return `<button class="weather-mini" data-action="weather" aria-label="查看目的地当前天气" aria-live="polite" aria-busy="${loading}">${weatherMiniContent(day)}</button>`;}
function paintWeather(){document.querySelectorAll('.weather-mini').forEach(el=>{el.innerHTML=weatherMiniContent();el.setAttribute('aria-busy',weatherEntry()?.status==='loading');});if(state.modal?.type==='weather'&&modal.open){const active=document.activeElement,focused=active?.dataset.action,scroll=modal.scrollTop;renderModal();if(['refresh-weather','close'].includes(focused))modal.querySelector(`[data-action="${focused}"]`)?.focus({preventScroll:true});modal.scrollTop=scroll;}}
async function refreshWeather(force=false,day=weatherDay()){
 const place=weatherPlaces[day],key=place[0],old=weatherCache.get(key);
 if(old?.status==='loading'||(!force&&old&&Date.now()-old.at<600000))return;
 weatherCache.set(key,{status:'loading',at:Date.now()});paintWeather();
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
 try{
  const query=new URLSearchParams({latitude:place[1],longitude:place[2],current:'temperature_2m,apparent_temperature,weather_code,precipitation,wind_speed_10m',timezone:place[3],timeformat:'unixtime',forecast_days:'1'});
  const response=await fetch('https://api.open-meteo.com/v1/forecast?'+query,{signal:controller.signal});
  if(!response.ok)throw new Error('Weather service unavailable');
  const json=await response.json(),data=json.current;
  if(!data||!['time','temperature_2m','weather_code','wind_speed_10m','apparent_temperature','precipitation'].every(k=>Number.isFinite(data[k]))||Math.abs(Date.now()/1000-data.time)>7200)throw new Error('Invalid or stale weather');
  weatherCache.set(key,{status:'ready',at:Date.now(),data});
 }catch(error){weatherCache.set(key,{status:'error',at:Date.now()});}
 finally{clearTimeout(timer);paintWeather();}
}
function stayButton(day=1){const stay=dayList[day].stay;if(!stay)return `<div class="helper">返程日 · 无当晚住宿</div>`;return `<button class="stay-line" data-action="stay" data-value="${day}"><span class="stay-icon">${icon('bed')}</span><span class="grow"><strong>${e(stay)}</strong><small>已确认住宿 · 入住时间待复核</small></span>${icon('chevron')}</button>`;}
function shortcuts(day=state.day){const date=dayList[day].date,photoCount=photos.filter(x=>x.date===date&&!x.demo).length;return `<div class="carry-shortcuts"><button data-action="carry" data-value="packing">行李<span class="tag">${dailyPacking(day).filter(x=>!x.checked).length} 项待带</span></button><button data-action="carry" data-value="documents">凭证<span class="tag">${documents.length} 份</span></button><button data-action="carry" data-value="album">相册<span class="tag">${photoCount} 张</span></button></div>`;}
function todayAgenda(day=state.day){const items=events.filter(x=>x.day===day&&['planned','confirmed'].includes(x.status)).slice(0,3);return `<div class="today-agenda">${items.map(x=>`<button data-action="event" data-value="${x.id}"><time>${e(x.time)}</time><span><strong>${e(x.title)}</strong><small>${e(x.place)}</small></span>${icon('chevron')}</button>`).join('')}</div>`;}
function todayRecords(dayIndex=state.day){const day=dayList[dayIndex].date,dayPhotos=photos.filter(x=>x.date===day&&!x.demo),dayExpenses=expenses.filter(x=>x.date===day&&x.currency==='EUR'&&!x.demo),spent=dayExpenses.reduce((sum,x)=>sum+x.myShare,0);return `<div class="record-grid"><button class="record-card" data-action="carry" data-value="album"><span class="caption">今天的照片</span>${dayPhotos.length?`<div class="record-photos">${dayPhotos.slice(0,2).map(p=>`<img src="${e(p.url)}" alt="">`).join('')}</div><strong>${dayPhotos.length} 张照片</strong>`:'<strong class="record-empty">还没有照片</strong>'}<small>添加或查看相册</small></button><button class="record-card" data-action="money-summary"><span class="caption">今天的开支</span>${dayExpenses.length?`<strong class="record-money">${money(spent,'EUR')}</strong>`:'<strong class="record-empty">暂无记录</strong>'}<small>打开费用记录</small></button></div>`;}
function homeA(){return `<div class="date-heading"><div><div class="eyebrow">10 月 02 日 · 周五 · 第 1 天</div><h1>抵达布达佩斯</h1></div>${weatherMini()}</div>
  <article class="ticket"><div class="ticket-head"><span class="label"><i></i>第一项安排</span><button data-action="timezone" aria-label="切换显示时区">${state.timezone==='local'?'中欧时间 06:20':'北京时间 12:20'} ⇄</button></div>
  <div class="ticket-main"><h2>机场进城，前往酒店</h2><p class="description">抵达日路线 · 10 月 02 日</p>
  <div class="station-grid"><div><h3>机场</h3><span class="station">Budapest Airport</span></div><span class="journey-symbol">${icon('train')}${icon('arrow')}</span><div class="end"><h3>城堡区</h3><span class="station">Hilton Budapest</span></div></div>
  <div class="departure"><div><div class="time text-time">抵达后</div><small>机场出发</small></div><div class="end"><div class="time">07:00</div><small>计划寄存行李</small></div></div><div class="ticket-meta"><span>100E 至 Deák 后继续导航</span><span>路线 · 待复核</span></div></div>
  <div class="ticket-foot"><div><small>今日第一站</small><span class="countdown">希尔顿寄存行李、整理休息</span></div>${linkButton('地点与提醒','event','d0e0')}</div></article>
  <button class="next-strip" data-action="event" data-value="d0e1"><span class="index">接着</span><div><strong>前往 Csészényi Café</strong><p>07:45–08:00 · Krisztina krt. 34</p></div>${icon('arrow')}</button>
  ${section('出行提醒')}<div class="card reminder"><h3>${icon('info')}100E 不直达酒店</h3><p class="reminder-text">机场票与市区票分开购买；到 Deák 后继续导航到城堡区，临近出发再核对运营班次。</p></div>
  ${section('今日安排',linkButton('完整行程','plan-today'))}${todayAgenda(0)}
  ${section('今晚住宿')}${stayButton(0)}
  ${section('随身准备',linkButton('全部','carry','documents'))}${shortcuts(0)}
  ${section('今天的记录')}${todayRecords(0)}`;}
function dateStrip(){return `<div class="date-strip" aria-label="行程日期">${dayList.map((d,i)=>`<button data-action="day" data-value="${i}" class="date-chip ${state.day===i?'active':''}" aria-pressed="${state.day===i}" aria-label="10月${i+2}日"><span>第 ${i+1} 天</span><b>${d.date.slice(-2)}</b><small>${d.week}</small></button>`).join('')}</div>`;}
function eventKind(x){return x.type==='bed'?'住宿':x.type==='train'||x.type==='plane'?'交通':x.type==='ticket'?'活动':x.type==='food'?'美食':'游览';}
function timeRank(value){const text=String(value),match=text.match(/^(\d{1,2}):(\d{2})/);if(match)return Number(match[1])*60+Number(match[2]);const named=[['清晨',360],['上午',480],['中午',720],['下午',840],['傍晚',1020],['晚上',1140]];return named.find(([label])=>text.includes(label))?.[1]??2000;}
function orderedEvents(list){return [...list].sort((a,b)=>timeRank(a.time)-timeRank(b.time));}
function eventRow(x){const status=x.bookingStatus==='confirmed'?'已定':x.status==='confirmed'?'已定':'计划',verify=x.verify?(x.status==='confirmed'&&x.type==='ticket'?' · 场次待复核':' · 待复核'):'';return `<article class="event-row"><div class="event-time">${e(x.time)}<small>${/^\d/.test(x.time)?'建议':'时段'} · 当地</small></div><div class="event-track">${icon(x.type)}</div><button class="event-card" data-action="event" data-value="${x.id}"><span class="tag">${eventKind(x)} · ${status}${verify}</span><h3>${e(x.title)}</h3><p>${e(x.place)}</p><span class="event-link">详情${x.documents.length?'与凭证':''}${icon('external')}</span></button></article>`;}
function optionCards(items,label){return items.length?`<div class="option-list">${items.map(x=>`<button class="option-card" data-action="event" data-value="${x.id}"><span>${e(label)} · ${e(x.time)}</span><strong>${e(x.title)}</strong><small>${e(x.place)}</small>${icon('chevron')}</button>`).join('')}</div>`:'';}
function concertBranch(branches){const selected=state.concertTime==='unknown'?[]:branches.filter(x=>x.time.startsWith(state.concertTime));return `${section('票面场次',`<span class="caption">官方晚场 19:00 · 票面待核</span>`)}${buttonsTabs([['19:00','19:00 晚场'],['15:30','15:30 下午场'],['unknown','待核']],state.concertTime,'concert-time')}${selected.length?optionCards(selected,'已选场次路线'):'<p class="branch-helper">官方日历已确认两个场次；当前按购买记忆默认 19:00，最终仍以票面为准。</p>'}`;}
function planPage(){const d=dayList[state.day],all=events.filter(x=>x.day===state.day),items=orderedEvents(all.filter(x=>['planned','confirmed'].includes(x.status))),branches=all.filter(x=>x.status==='conditional'),food=all.filter(x=>x.status==='candidate');return `${heading('完整行程','10 月 02 日 — 10 月 09 日 · 中欧')}
  <div class="route-strip"><span>布达佩斯</span>${icon('arrow')}<span>维也纳</span>${icon('arrow')}<span>湖区</span>${icon('arrow')}<span>布拉格</span></div>${dateStrip()}
  <div class="date-heading plan-day-heading"><div>${section(e(d.place),`<span class="caption">${e(d.route)} · ${items.length} 项主安排</span>`)}</div>${weatherMini()}</div>
  <button class="secondary full itinerary-edit-cta itinerary-edit-cta-top" data-action="edit-day" data-value="${state.day}">${icon('plus')}编辑当日行程</button>
  <div class="timeline">${items.map(eventRow).join('')}</div>
  ${state.day===1?concertBranch(branches):branches.length?section('按天气 / 体力决定',`<span class="caption">${branches.length} 项</span>`)+optionCards(branches,'条件分支'):''}
  ${food.length?section('顺路美食',`<span class="caption">不占固定时段</span>`)+optionCards(food,'美食候选'):''}`;}
function fileRow(d){return `<button class="file-row" data-action="document" data-value="${d.id}"><span class="file-icon">${icon(d.type==='住宿'?'bed':d.type==='交通'?'train':'document')}</span><span class="grow"><h3>${e(d.name)}</h3><p>${e(d.type)} · ${e(d.size)}${d.demo?' · 演示':''}</p></span>${icon('eye')}</button>`;}
function documentsView(){const list=documents.filter(x=>state.docFilter==='全部'||x.type===state.docFilter);return `<div class="document-intro"><div><h2>随身文件夹</h2><small>${documents.length} 份资料</small></div><button class="icon-btn" data-action="import-doc" aria-label="导入文件">${icon('plus')}</button></div>
  <div class="chips">${['全部','交通','住宿','证件','其他'].map(x=>`<button data-action="doc-filter" data-value="${x}" class="${x===state.docFilter?'active':''}" aria-pressed="${x===state.docFilter}">${x}</button>`).join('')}</div>
  <div class="file-list">${list.map(fileRow).join('')||'<div class="empty">此分类还没有文件</div>'}</div><button class="secondary full spaced" data-action="import-doc">${icon('plus')}导入 PDF 或图片</button><p class="helper">本次预览中可打开、下载与关联文件。刷新页面后，导入的文件会清空。</p>`;}
function packingView(){const items=state.packMode==='trip'?packing.trip:dailyPacking(state.day),done=items.filter(x=>x.checked).length;return `${buttonsTabs([['trip','出发装箱'],['daily','当日随身']],state.packMode,'pack-mode')}<div class="between"><span class="caption">${state.packMode==='trip'?'整段旅程':`${dayList[state.day].date.slice(5).replace('-',' 月 ')} 日 · ${e(dayList[state.day].place)}`}</span><button class="text-link" data-action="add-item">${icon('plus')}添加物品</button></div><div class="packing-summary"><h2>${state.packMode==='trip'?'出发前收好':'出门前带好'}</h2><div><b>${done}</b><span class="sub"> / ${items.length}</span></div></div><div class="progress"><i style="width:${items.length?done/items.length*100:0}%"></i></div><div>${items.map(x=>`<label class="check-row ${x.checked?'done':''}"><input type="checkbox" data-check="${x.id}" ${x.checked?'checked':''}><span class="label">${e(x.name)}</span>${x.required?'<small>必带</small>':''}</label>`).join('')}</div><p class="helper">装箱与每日随身清单独立勾选。</p>`;}
function albumView(){if(state.albumGroup){const list=photos.filter(p=>p.group===state.albumGroup);return `<div class="between"><button class="text-link" data-action="album-back">${icon('back')}全部相册</button><button class="text-link" data-action="import-photo">${icon('plus')}添加照片</button></div><div class="section-title"><h2>${e(state.albumGroup)}</h2><small>${list.length} 张</small></div><div class="photo-grid">${list.map(p=>`<button data-action="photo" data-value="${p.id}" aria-label="查看照片 ${e(p.name)}"><img src="${e(p.url)}" alt="${e(p.name)}"></button>`).join('')}</div>${!list.length?'<div class="empty">添加第一张照片</div>':''}`;}
  const groups=[...new Set(photos.map(p=>p.group))];return `<div class="between"><h2>旅行相册</h2><button class="icon-btn" data-action="import-photo" aria-label="添加照片">${icon('plus')}</button></div><div class="album-grid">${groups.map(g=>{const group=photos.filter(p=>p.group===g);return `<button class="album-card" data-action="album-group" data-value="${e(g)}"><div class="album-stack"><img src="${e(group[0].url)}" alt="${e(g)}相册封面"></div><div><h3>${e(g)}</h3><small>${group.length} 张${group.every(x=>x.demo)?' · 摄影示例':''}</small></div></button>`;}).join('')}<button class="album-card" data-action="import-photo"><div class="new-album"><span>${icon('plus')}</span></div><div><h3>添加旅行照片</h3><small>选择手机里的照片</small></div></button></div>`;}
function carryPage(){return `${heading('随身','文件、行李与一路的照片')}${buttonsTabs([['documents','凭证'],['packing','行李'],['album','相册']],state.carry,'carry-tab')}${state.carry==='documents'?documentsView():state.carry==='packing'?packingView():albumView()}`;}
function finances(currency=state.currency){const all=expenses.filter(x=>x.currency===currency);const paid=all.filter(x=>x.status==='已支付');return {paid:paid.reduce((a,x)=>a+x.myShare,0),pending:all.filter(x=>x.status==='待支付').reduce((a,x)=>a+x.myShare,0),receive:paid.filter(x=>x.payer==='我').reduce((a,x)=>a+x.cents-x.myShare,0),owe:paid.filter(x=>x.payer==='同行人').reduce((a,x)=>a+x.myShare,0),all,actual:paid};}
function budgetView(){const f=finances(),budget=budgets[state.currency]||0;return `<div class="budget-card"><div class="between"><span class="caption">${budget?'我的剩余预算':'我的实际承担'}</span><button class="text-link" data-action="budget">设置预算</button></div><div class="budget-number"><small>${state.currency}</small>${money(budget?budget-f.paid:f.paid,state.currency).replace(/[^\d.,−\-]/g,'')}</div><div class="progress"><i style="width:${budget?Math.min(100,f.paid/budget*100):0}%"></i></div><div class="budget-stats"><div><span>已支付 · 我的份额</span><b>${money(f.paid,state.currency)}</b></div><div><span>待支付 · 我的份额</span><b>${money(f.pending,state.currency)}</b></div></div></div>
  <div class="balance-pair"><button data-action="balance" data-value="receive"><small>待收回 ${icon('chevron')}</small><b>${money(f.receive,state.currency)}</b></button><button data-action="balance" data-value="owe"><small>待支付给同行人 ${icon('chevron')}</small><b>${money(f.owe,state.currency)}</b></button></div>
  ${section('分类支出',`<small>我的实际承担</small>`)}<div class="category-grid">${Object.entries(categoryIcons).map(([cat,ic])=>{const cents=f.actual.filter(x=>x.category===cat).reduce((a,x)=>a+x.myShare,0);return `<button class="category" data-action="expense-category" data-value="${cat}"><div class="between">${icon(ic)}<b>${cat}</b><small>${money(cents,state.currency)}</small></div><div class="progress"><i style="width:${f.paid?cents/f.paid*100:0}%"></i></div><small>${f.paid?Math.round(cents/f.paid*100):0}% 的支出</small></button>`;}).join('')}</div>`;}
function expenseList(){const list=finances().all.filter(x=>state.expenseCategory==='全部'||x.category===state.expenseCategory);const dates=[...new Set(list.map(x=>x.date))].sort().reverse();return `<div class="chips">${['全部',...Object.keys(categoryIcons)].map(c=>`<button data-action="expense-filter" data-value="${c}" class="${c===state.expenseCategory?'active':''}" aria-pressed="${c===state.expenseCategory}">${c}</button>`).join('')}</div>${dates.map(d=>`${section(d.slice(5).replace('-',' 月 ')+' 日',`<small>${list.filter(x=>x.date===d).length} 笔</small>`)}${list.filter(x=>x.date===d).map(x=>`<button class="expense-row" data-action="edit-expense" data-value="${x.id}"><span class="expense-symbol">${icon(categoryIcons[x.category])}</span><span class="grow"><h3>${e(x.title)}</h3><small>${e(x.payer)}付款 · ${x.split?'两人分摊':'个人支出'} · ${x.status}</small></span><span class="amount">${money(x.cents,x.currency)}<small>我承担 ${money(x.myShare,x.currency)}</small></span></button>`).join('')}`).join('')||'<div class="empty">此分类暂无账单</div>'}`;}
function moneyPage(){return `${heading('旅行费用','预算、明细与同行分摊',`<button class="icon-btn" data-action="new-expense" aria-label="记一笔">${icon('plus')}</button>`)}${buttonsTabs([['summary','总览'],['details','明细']],state.expenseTab,'expense-tab')}<div class="currency-bar"><small>原币独立汇总 <span class="sample-marker">示例账本</span></small><select aria-label="账本币种" id="ledger-currency">${['EUR','CNY','HUF','CZK'].map(c=>`<option ${c===state.currency?'selected':''}>${c}</option>`).join('')}</select></div>${state.expenseTab==='summary'?budgetView():expenseList()}`;}
let renderedRoute='';
function focusIdentity(el){if(!el||!el.closest('#main,#nav'))return null;if(el.dataset.action){const value=el.dataset.value;return `[data-action="${el.dataset.action}"]${value!==undefined?`[data-value="${value}"]`:''}`;}if(el.dataset.check)return `[data-check="${el.dataset.check}"]`;if(el.id)return `#${el.id}`;return null;}
function render(){const focusTarget=focusIdentity(document.activeElement),previousRoute=renderedRoute;document.body.className='variant-a';const main=$('#main');main.innerHTML=state.page==='now'?homeA():state.page==='plan'?planPage():state.page==='carry'?carryPage():moneyPage();$('#nav').innerHTML=[['now','compass','当下'],['plan','calendar','行程'],['carry','folder','随身'],['money','wallet','费用']].map(([id,ic,label])=>`<a href="#${id==='carry'?'carry/'+state.carry:id}" ${state.page===id?'aria-current="page"':''} class="${state.page===id?'active':''}">${icon(ic)}<span>${label}</span></a>`).join('');const route=`${state.page}/${state.page==='carry'?state.carry:''}`,routeChanged=route!==renderedRoute;if(routeChanged){main.classList.remove('page-enter');void main.offsetWidth;main.classList.add('page-enter');renderedRoute=route;}if(!previousRoute)return;if(routeChanged){const heading=main.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});requestAnimationFrame(()=>heading.isConnected&&heading.focus({preventScroll:true}));}}else if(focusTarget){document.querySelector(focusTarget)?.focus({preventScroll:true});}}
function modalHeader(title){return `<div class="handle"></div><div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭详情">${icon('close')}</button></div>`;}
function openModal(type,id=null,push=false){if(!modal.open){state.trigger=document.activeElement;state.modalHistory=[];}else if(push)state.modalHistory.push(state.modal);state.modal={type,id};renderModal();if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){const form=modal.querySelector('form');if(form?.dataset.dirty==='true'&&!window.confirm('放弃尚未保存的修改？'))return;if(state.modalHistory.length){state.modal=state.modalHistory.pop();renderModal();return;}modal.close();state.modal=null;state.trigger?.isConnected&&state.trigger.focus();}
function mapLink(place){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(place)}`;}
function eventDetail(x){const statusLabel=x.bookingStatus==='confirmed'?'住宿已确认 · 执行时间为计划':({confirmed:'已定节点',planned:'计划安排',conditional:'条件分支',candidate:'美食候选'}[x.status]||'计划安排');const timeLabel=x.status==='candidate'?`${e(x.time)} · 无固定时段，按距离与现场情况选择`:`${e(x.time)} · 中欧当地时间${x.verify?' · 出发前复核':'（建议时段）'}`;return `${modalHeader(e(x.title))}<p class="caption">${e(x.place)}</p><div class="detail-status spaced">${icon(x.type)}${statusLabel}${x.verify?' · 出发前复核':''}</div><div class="detail-row">${icon('calendar')}<div><strong>${x.date.slice(5).replace('-',' 月 ')} 日 · ${dayList[x.day].week}</strong><p>${timeLabel}</p></div></div><div class="detail-row">${icon('pin')}<div><strong>${e(x.place)}</strong><p>地图按地点名称搜索，出发前核对目标地点。</p></div></div><div class="detail-actions"><a class="secondary" href="${mapLink(x.place.split(' → ')[0])}" target="_blank" rel="noopener">地图导航 ${icon('external')}</a><button class="secondary" data-action="edit-event" data-value="${x.id}">${icon('plus')}编辑安排</button></div><div class="detail-note">${e(x.note)}</div>${section('相关凭证',`<button class="text-link" data-action="attach" data-value="${x.id}">${icon('plus')}关联</button>`)}<div class="file-list">${x.documents.map(id=>documents.find(d=>d.id===id)).filter(Boolean).map(fileRow).join('')||'<div class="empty">暂无关联凭证</div>'}</div><p class="helper">资料来源：原旅行手札的行程摘要。待复核内容不是已出票、已预订或实时开放信息。</p>`;}
function stayDetail(day){const related=events.find(x=>x.day===day&&x.type==='bed'&&x.bookingStatus==='confirmed');if(related)return eventDetail(related);const d=dayList[day];return `${modalHeader(e(d.stay||'当日住宿'))}<div class="detail-status">${icon('bed')}${d.stay?'已确认住宿 · 入住时间待复核':'返程日 · 无当晚住宿'}</div>${d.stay?`<div class="detail-row">${icon('calendar')}<div><strong>${d.date.slice(5).replace('-',' 月 ')} 日当晚</strong><p>入住与退房时间以订单为准</p></div></div><a class="secondary full" href="${mapLink(d.stay)}" target="_blank" rel="noopener">搜索酒店位置 ${icon('external')}</a>`:''}`;}
function documentDetail(d){return `${modalHeader(e(d.name))}<p class="caption">${e(d.type)} · ${e(d.size)}</p>${d.demo?`<div class="doc-preview spaced"><span class="doc-stamp">DESIGN SAMPLE</span><h3>${e(d.name)}</h3><p style="white-space:pre-line">${e(d.text)}</p></div>`:d.mime.startsWith('image/')?`<img class="photo-preview spaced" src="${e(d.url)}" alt="${e(d.name)}">`:`<div class="doc-preview spaced">${icon('document')}<h3>${e(d.name)}</h3><p>在浏览器中打开 PDF 原件，或下载保存。</p><a class="secondary full spaced" href="${e(d.url)}" target="_blank" rel="noopener">打开 PDF ${icon('external')}</a></div>`}<div class="form-footer"><button class="secondary" data-action="download-doc" data-value="${d.id}">${icon('download')}下载</button><button class="secondary" data-action="classify-doc" data-value="${d.id}">修改分类</button></div>`;}
function attachDetail(eventId){const x=events.find(v=>v.id===eventId);return `${modalHeader('关联凭证')}<p class="caption">${e(x.title)}</p><div class="spaced">${documents.map(d=>`<label class="check-row"><input type="checkbox" data-attach="${d.id}" data-event="${eventId}" ${x.documents.includes(d.id)?'checked':''}><span class="label">${e(d.name)}</span><small>${e(d.type)}</small></label>`).join('')}</div><button class="secondary full spaced" data-action="import-for-event" data-value="${eventId}">${icon('plus')}导入新文件</button><button class="solid full spaced" data-action="close">完成</button>`;}
function weatherDetail(){const day=weatherDay(),w=weatherEntry(day),city=weatherPlaces[day][0],d=w?.data;return `${modalHeader(e(city)+' · 当前天气')}<p class="caption">目的地现在的天气 · 非旅行日预报</p>${w?.status==='ready'?`<div class="weather-large"><div><strong>${Math.round(d.temperature_2m)}°</strong><p class="sub">${weatherWords(d.weather_code)} · 体感 ${Math.round(d.apparent_temperature)}°</p></div>${icon(d.weather_code===0?'sun':'cloud')}</div><p class="caption">${weatherStamp(d.time,day)} 更新 · ${e(weatherPlaces[day][3])}</p><div class="weather-metrics"><div><small>降水量</small>${d.precipitation} mm</div><div><small>风速</small>${d.wind_speed_10m} km/h</div></div>`:`<div class="empty" role="status">${w?.status==='error'?'天气暂不可用，请检查网络后重试。':'正在获取当前天气…'}</div>`}<button class="secondary full spaced" data-action="refresh-weather" aria-disabled="${w?.status==='loading'}">刷新天气</button><p class="helper">来源：<a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a> · 当前天气为模型估算，每 10 分钟刷新。旅行尚未开始时，也显示目的地今天的天气。</p>`;}
function expenseForm(id){const x=expenses.find(x=>x.id===id)||{title:'',cents:0,currency:state.currency,date:dayList[state.day].date,category:'餐饮',payer:'我',split:false,myShare:0,status:'已支付',method:'银行卡'};return `${modalHeader(id?'编辑账单':'记一笔')}<form id="expense-form" data-id="${id||''}"><div class="field-grid"><label class="field"><span>金额</span><input name="amount" type="number" step="0.01" min="0.01" inputmode="decimal" value="${x.cents?x.cents/100:''}" placeholder="0.00" required></label><label class="field"><span>币种</span><select name="currency">${['EUR','CNY','HUF','CZK'].map(v=>`<option ${v===x.currency?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field"><span>这笔花在哪</span><input name="title" value="${e(x.title)}" placeholder="例如：两人午餐" required></label><div class="field-grid"><label class="field"><span>分类</span><select name="category">${Object.keys(categoryIcons).map(v=>`<option ${v===x.category?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>日期</span><input type="date" name="date" value="${x.date}" required></label></div><div class="field-grid"><label class="field"><span>付款人</span><select name="payer">${['我','同行人'].map(v=>`<option ${v===x.payer?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>支付状态</span><select name="status">${['已支付','待支付'].map(v=>`<option ${v===x.status?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field"><span>支付方式</span><select name="method">${['银行卡','现金','其他'].map(v=>`<option ${v===x.method?'selected':''}>${v}</option>`).join('')}</select></label><label class="inline-field"><span>${icon('people')} 与同行人分摊</span><input name="split" type="checkbox" ${x.split?'checked':''}></label><div id="split-options" ${x.split?'':'hidden'}><label class="field"><span>分摊方式</span><select name="splitMode"><option value="equal">两人均分</option><option value="custom" ${x.split&&x.myShare!==Math.ceil(x.cents/2)?'selected':''}>自定义我的份额</option></select></label><label class="field" id="share-field" ${x.split&&x.myShare!==Math.ceil(x.cents/2)?'':'hidden'}><span>我承担的金额</span><input name="share" inputmode="decimal" type="number" step="0.01" min="0" value="${x.myShare/100}"></label></div><div class="split-note" id="split-preview"></div><p class="form-error" id="form-error" role="alert"></p><div class="form-footer">${id?`<button type="button" class="secondary" data-action="delete-expense" data-value="${id}">删除</button>`:''}<button class="solid" type="submit">保存账单</button></div></form>`;}
function dayLabel(day){return dayList[day].date.slice(5).replace('-',' 月 ')+' 日';}
function dayEditor(day){const list=orderedEvents(events.filter(x=>x.day===day));return `${modalHeader(`编辑 ${dayLabel(day)}行程`)}<p class="caption">按时间整理景点、交通、美食、活动与住宿。点选已有安排可修改或删除。</p><div class="itinerary-editor-list">${list.map(x=>`<button class="itinerary-edit-row" data-action="edit-event" data-value="${x.id}" aria-label="编辑 ${e(x.title)}"><time>${e(x.time)}</time><span class="itinerary-edit-icon">${icon(x.type)}</span><span><strong>${e(x.title)}</strong><small>${eventKind(x)} · ${e(x.place)}</small></span>${icon('chevron')}</button>`).join('')}</div><button class="solid full" data-action="add-event" data-value="${day}">${icon('plus')}新增安排</button><p class="helper">修改会保存在当前浏览器；清除该网站的浏览器数据后恢复默认行程。</p>`;}
function eventForm(key){const isNew=String(key).startsWith('new:'),found=isNew?null:events.find(x=>x.id===key),day=isNew?Number(String(key).slice(4)):found.day,x=found||{time:'',title:'',place:'',type:'walk',note:''};return `${modalHeader(found?'编辑安排':'新增安排')}<form id="event-form" data-id="${found?e(found.id):''}" data-day="${day}"><p class="caption">${dayLabel(day)} · ${e(dayList[day].place)}</p><div class="field-grid"><label class="field"><span>时间</span><input name="time" inputmode="numeric" placeholder="例如 09:30" value="${e(x.time)}" required></label><label class="field"><span>类型</span><select name="type">${[['walk','景点'],['train','交通'],['food','美食'],['ticket','活动'],['bed','住宿'],['plane','航班']].map(([value,label])=>`<option value="${value}" ${x.type===value?'selected':''}>${label}</option>`).join('')}</select></label></div><label class="field"><span>名称</span><input name="title" value="${e(x.title)}" placeholder="例如：湖岸慢走" required></label><label class="field"><span>地点 / 路线</span><input name="place" value="${e(x.place)}" placeholder="例如：Gosau → Gosausee" required></label><label class="field"><span>提醒</span><textarea name="note" placeholder="交通、预约或体力提醒">${e(x.note)}</textarea></label><p class="form-error" id="form-error" role="alert"></p><div class="form-footer">${found?`<button type="button" class="secondary" data-action="delete-event" data-value="${found.id}">删除安排</button>`:''}<button class="solid" type="submit">保存安排</button></div></form>`;}
function renderModal(){const {type,id}=state.modal;let html='';
  if(type==='event')html=eventDetail(events.find(x=>x.id===id));
  if(type==='stay')html=stayDetail(Number(id));
  if(type==='document')html=documentDetail(documents.find(x=>x.id===id));
  if(type==='attach')html=attachDetail(id);
  if(type==='weather')html=weatherDetail();
  if(type==='expense')html=expenseForm(id);
  if(type==='day-editor')html=dayEditor(Number(id));
  if(type==='event-form')html=eventForm(id);
  if(type==='budget')html=`${modalHeader('设置个人预算')}<form id="budget-form"><label class="field"><span>总预算 · ${state.currency}</span><input name="budget" type="number" min="0" step="0.01" value="${(budgets[state.currency]||0)/100}" required></label><p class="helper">按我的承担份额扣减已支付金额，待支付单列。不同币种独立计算。</p><button class="solid full spaced">保存预算</button></form>`;
  if(type==='balance'){const f=finances(),receive=id==='receive',list=f.actual.filter(x=>receive?x.payer==='我'&&x.cents>x.myShare:x.payer==='同行人'&&x.myShare>0);html=`${modalHeader(receive?'同行人待付给我':'我待付给同行人')}<div class="budget-number" style="font-size:35px">${money(receive?f.receive:f.owe,state.currency)}</div><div class="spaced">${list.map(x=>`<button class="expense-row" data-action="edit-expense" data-value="${x.id}"><span class="grow"><h3>${e(x.title)}</h3><small>${x.date}</small></span><span>${money(receive?x.cents-x.myShare:x.myShare,x.currency)}</span></button>`).join('')||'<div class="empty">没有待结算记录</div>'}</div><p class="helper">根据已支付账单的付款人和份额计算，尚未抵扣任何线下结算。</p>`;}
  if(type==='photo'){const p=photos.find(x=>x.id===id);html=`${modalHeader(e(p.name))}<img class="photo-preview" src="${e(p.url)}" alt="${e(p.name)}"><p class="photo-meta">${e(p.group)} · ${p.demo?'风景参考图片，非旅行实拍':e(p.date)}</p><div class="form-footer"><button class="secondary" data-action="photo-prev">上一张</button><button class="secondary" data-action="photo-next">下一张</button></div><button class="small-delete" data-action="delete-photo" data-value="${p.id}">删除照片</button>`;}
  if(type==='add-item')html=`${modalHeader('添加随身物品')}<form id="item-form"><label class="field"><span>物品名称</span><input name="name" placeholder="例如：太阳镜" required></label><label class="inline-field"><span>标为必带</span><input type="checkbox" name="required"></label><button class="solid full spaced">添加</button></form>`;
  if(type==='classify'){const d=documents.find(x=>x.id===id);html=`${modalHeader('文件分类')}<form id="classify-form" data-id="${id}"><p class="caption">${e(d.name)}</p><label class="field"><span>保存到</span><select name="category">${['交通','住宿','证件','其他'].map(v=>`<option ${v===d.type?'selected':''}>${v}</option>`).join('')}</select></label><button class="solid full">保存分类</button></form>`;}
  if(type==='trip')html=`${modalHeader('中欧八日')}<div class="about-lines"><p><strong>10 月 02 日 — 10 月 09 日</strong><br>布达佩斯 → 维也纳 → 奥地利湖区 → 布拉格</p><p>当下页从 <strong>10 月 02 日抵达布达佩斯</strong> 开始，展示第一天的交通、安排与住宿。天气显示目的地当前状况和当地更新时间。</p><p>行程页面可浏览全部日期，不改变当下页的第一项安排。</p></div><button class="solid full spaced" data-action="jump-plan">查看完整行程</button>`;
  if(type==='about')html=`${modalHeader('A · 随行票夹')}<div class="about-lines"><p>下一项安排集中在一张旅行票中；完整行程按主安排、条件分支和顺路美食分层阅读。</p><p>可切日期、查看详情、导入文件与照片、勾选行李、记账、编辑和分摊。行程编辑会保存在当前浏览器。</p><p>天气来自在线服务；费用、文件和相册包含演示内容；标注“出发前复核”的交通、营业和场次需要在旅行前再次确认。</p></div>`;
  modal.innerHTML=html;if(type==='expense')updateSplitPreview();
}
function updateSplitPreview(){const form=$('#expense-form');if(!form)return;const amount=Math.round(Number(form.elements.amount.value)*100)||0;const split=form.elements.split.checked;const currency=form.elements.currency.value;const custom=form.elements.splitMode.value==='custom';$('#split-options').hidden=!split;$('#share-field').hidden=!split||!custom;const share=split?(custom?Math.round(Number(form.elements.share.value)*100)||0:Math.ceil(amount/2)):amount;$('#split-preview').textContent=split?`我承担 ${money(share,currency)} · 同行人承担 ${money(amount-share,currency)}`:`个人支出 · 我承担 ${money(amount,currency)}`;}
function finishForm(message){const form=modal.querySelector('form');if(form)form.dataset.dirty='false';state.modalHistory=[];modal.close();state.modal=null;render();notify(message);}
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action]');if(!b)return;const {action,value}=b.dataset;
  const modalActions={about:'about',trip:'trip',weather:'weather',event:'event',stay:'stay',document:'document',attach:'attach',photo:'photo',balance:'balance',budget:'budget','add-item':'add-item','classify-doc':'classify','edit-day':'day-editor'};
  if(modalActions[action]){openModal(modalActions[action],value,modal.open);return;}
  if(action==='add-event'){openModal('event-form',`new:${value}`,true);return;}
  if(action==='edit-event'){openModal('event-form',value,true);return;}
  if(action==='refresh-weather'){refreshWeather(true);return;}
  if(action==='close'){closeModal();return;}
  if(action==='timezone'){state.timezone=state.timezone==='local'?'beijing':'local';render();}
  if(action==='day'){state.day=Number(value);render();$('#main .date-chip.active')?.scrollIntoView({block:'nearest',inline:'center'});}
  if(action==='concert-time'){state.concertTime=value;render();}
  if(action==='plan-today'||action==='jump-plan'){if(modal.open){modal.close();state.modal=null;}state.day=0;navigate('plan');}
  if(action==='carry'){state.albumGroup=null;navigate('carry',value);}
  if(action==='carry-tab'){state.albumGroup=null;navigate('carry',value);}
  if(action==='money-summary'){navigate('money');}
  if(action==='daily-packing'){state.packMode='daily';navigate('carry','packing');}
  if(action==='pack-mode'){state.packMode=value;render();}
  if(action==='doc-filter'){state.docFilter=value;render();}
  if(action==='import-doc'||action==='import-for-event'){state.attachEvent=action==='import-for-event'?value:null;$('#document-input').click();}
  if(action==='import-photo'){state.importPhotosGroup=state.albumGroup||'我的旅途';$('#photo-input').click();}
  if(action==='album-group'){state.albumGroup=value;render();}
  if(action==='album-back'){state.albumGroup=null;render();}
  if(action==='photo-prev'||action==='photo-next'){const p=photos.find(p=>p.id===state.modal.id);const list=photos.filter(x=>x.group===p.group);const index=list.indexOf(p);state.modal.id=list[(index+(action==='photo-next'?1:-1)+list.length)%list.length].id;renderModal();}
  if(action==='delete-photo'){const p=photos.find(x=>x.id===value);if(!confirm(`删除“${p.name}”？`))return;photos=photos.filter(x=>x.id!==value);state.modalHistory=[];modal.close();state.modal=null;if(!photos.some(x=>x.group===state.albumGroup))state.albumGroup=null;render();notify('照片已从本次预览移除');}
  if(action==='expense-tab'){state.expenseTab=value;render();}
  if(action==='expense-category'){state.expenseCategory=value;state.expenseTab='details';render();}
  if(action==='expense-filter'){state.expenseCategory=value;render();}
  if(action==='new-expense'||action==='edit-expense'){openModal('expense',action==='edit-expense'?value:null,modal.open);}
  if(action==='delete-expense'){if(!confirm('删除这笔账单？'))return;expenses=expenses.filter(x=>x.id!==value);finishForm('账单已删除，金额已更新');}
  if(action==='delete-event'){const index=events.findIndex(x=>x.id===value);if(index<0||!confirm(`删除“${events[index].title}”？`))return;events.splice(index,1);persistEvents();finishForm('安排已从当天时间线删除');}
  if(action==='download-doc'){const d=documents.find(x=>x.id===value);const a=document.createElement('a');const local=d.demo?URL.createObjectURL(new Blob([d.text],{type:'text/plain;charset=utf-8'})):d.url;a.href=local;a.download=d.name+(d.demo?'.txt':'');a.click();if(d.demo)setTimeout(()=>URL.revokeObjectURL(local),1000);}
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='ledger-currency'){state.currency=el.value;render();}
  if(el.dataset.check){const list=state.packMode==='trip'?packing.trip:dailyPacking(state.day);list.find(x=>x.id===el.dataset.check).checked=el.checked;render();}
  if(el.dataset.attach){const x=events.find(x=>x.id===el.dataset.event);x.documents=el.checked?[...new Set([...x.documents,el.dataset.attach])]:x.documents.filter(v=>v!==el.dataset.attach);persistEvents();}
});
modal.addEventListener('input',event=>{const form=event.target.closest('form');if(form)form.dataset.dirty='true';if(form?.id==='expense-form')updateSplitPreview();});
modal.addEventListener('change',event=>{const form=event.target.closest('form');if(form)form.dataset.dirty='true';if(form?.id==='expense-form')updateSplitPreview();});
modal.addEventListener('cancel',event=>{event.preventDefault();closeModal();});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.addEventListener('submit',event=>{
  event.preventDefault();const form=event.target,fd=new FormData(form);
  if(form.id==='expense-form'){
    const cents=Math.round(Number(fd.get('amount'))*100);const split=fd.has('split');const myShare=split?(fd.get('splitMode')==='custom'?Math.round(Number(fd.get('share'))*100):Math.ceil(cents/2)):cents;
    if(!Number.isSafeInteger(cents)||cents<=0||cents>1000000000||!Number.isSafeInteger(myShare)||myShare<0||myShare>cents){$('#form-error').textContent='请检查金额：我的份额须在 0 与账单总额之间。';return;}
    const entry={id:form.dataset.id||uid(),title:fd.get('title').trim(),cents,currency:fd.get('currency'),date:fd.get('date'),category:fd.get('category'),payer:fd.get('payer'),split,myShare,status:fd.get('status'),method:fd.get('method')};
    if(!entry.title){$('#form-error').textContent='请填写这笔账单的说明。';return;}
    const index=expenses.findIndex(x=>x.id===entry.id);if(index>=0)expenses[index]=entry;else expenses.push(entry);state.currency=entry.currency;finishForm('账单已保存到本次预览');
  }
  if(form.id==='event-form'){
    const day=Number(form.dataset.day),time=String(fd.get('time')||'').trim(),title=String(fd.get('title')||'').trim(),place=String(fd.get('place')||'').trim(),type=String(fd.get('type')||'walk'),note=String(fd.get('note')||'').trim();
    if(!time||!title||!place){$('#form-error').textContent='请填写时间、名称和地点。';return;}
    const index=events.findIndex(x=>x.id===form.dataset.id),old=index>=0?events[index]:null;
    const entry={id:old?.id||uid(),day,time,title,place,type,note,date:dayList[day].date,status:old?.status||'planned',verify:old?.verify??['train','plane'].includes(type),bookingStatus:old?.bookingStatus||null,documents:old?.documents||[]};
    if(index>=0)events[index]=entry;else events.push(entry);persistEvents();state.day=day;finishForm(index>=0?'行程已更新':'安排已加入当天时间线');
  }
  if(form.id==='budget-form'){budgets[state.currency]=Math.round(Number(fd.get('budget'))*100);finishForm('个人预算已更新');}
  if(form.id==='item-form'){const name=fd.get('name').trim();if(!name)return;const list=state.packMode==='trip'?packing.trip:dailyPacking(state.day);list.push({id:uid(),name,checked:false,required:fd.has('required')});finishForm('物品已添加');}
  if(form.id==='classify-form'){documents.find(x=>x.id===form.dataset.id).type=fd.get('category');form.dataset.dirty='false';closeModal();render();notify('文件分类已更新');}
});
$('#document-input').addEventListener('change',event=>{
  let count=0;for(const f of event.target.files){if(!f.type.startsWith('image/')&&f.type!=='application/pdf')continue;const d={id:uid(),name:f.name,mime:f.type,url:URL.createObjectURL(f),type:state.attachEvent?(events.find(x=>x.id===state.attachEvent).type==='bed'?'住宿':'交通'):'其他',size:f.size<1048576?Math.max(1,Math.round(f.size/1024))+' KB':(f.size/1048576).toFixed(1)+' MB'};documents.push(d);if(state.attachEvent)events.find(x=>x.id===state.attachEvent).documents.push(d.id);count++;}if(state.attachEvent)persistEvents();
  event.target.value='';render();if(modal.open)renderModal();notify(count?`已导入 ${count} 份文件，仅保留在本次预览`:'请选择 PDF 或图片');
});
$('#photo-input').addEventListener('change',event=>{
  let count=0;for(const f of event.target.files){if(!f.type.startsWith('image/'))continue;photos.push({id:uid(),name:f.name,url:URL.createObjectURL(f),date:dayList[state.day].date,group:state.importPhotosGroup});count++;}event.target.value='';if(count){state.albumGroup=state.importPhotosGroup;state.carry='album';navigate('carry','album');}notify(count?`已添加 ${count} 张照片，仅保留在本次预览`:'请选择图片文件');
});
window.addEventListener('hashchange',()=>{parseHash();render();});
setInterval(()=>{if(!document.hidden)refreshWeather();},600000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshWeather();});
parseHash();render();
